function money(value: number, currency: string) {
  try { return new Intl.NumberFormat('en', { style: 'currency', currency, maximumFractionDigits: 0 }).format(value); }
  catch { return `${currency} ${value.toLocaleString()}`; }
}
function initials(name: string) { return name.split(' ').map((part) => part[0]).slice(0, 2).join('').toUpperCase(); }
function dateLabel(date?: string) {
  if (!date) return '—';
  const parsed = new Date(date);
  return Number.isNaN(parsed.getTime()) ? date : new Intl.DateTimeFormat('en', { month: 'short', day: 'numeric', year: 'numeric' }).format(parsed);
}

function Button({ children, variant = 'primary', onClick, type = 'button', disabled = false, className = '', testId = 'button-action' }: { children: ReactNode; variant?: 'primary' | 'soft' | 'outline' | 'ghost' | 'danger'; onClick?: () => void; type?: 'button' | 'submit'; disabled?: boolean; className?: string; testId?: string }) {
  return <button type={type} onClick={onClick} disabled={disabled} data-testid={testId} className={`inline-flex items-center justify-center gap-2 rounded-lg px-4 py-2.5 text-sm font-bold transition hover:-translate-y-0.5 disabled:cursor-not-allowed disabled:opacity-50 ${variant === 'primary' ? 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))] shadow-sm' : variant === 'soft' ? 'bg-[hsl(var(--secondary))] text-[hsl(var(--secondary-foreground))]' : variant === 'danger' ? 'bg-[hsl(var(--destructive))] text-[hsl(var(--destructive-foreground))]' : variant === 'outline' ? 'border border-border bg-card text-foreground hover:bg-muted' : 'text-muted-foreground hover:bg-muted hover:text-foreground'} ${className}`}>{children}</button>;
}
function Badge({ children, tone = 'neutral' }: { children: ReactNode; tone?: 'neutral' | 'teal' | 'orange' | 'green' | 'red' }) {
  const colors = { neutral: 'bg-muted text-muted-foreground', teal: 'bg-[hsl(var(--primary)/.12)] text-[hsl(var(--primary))]', orange: 'bg-[hsl(var(--accent)/.16)] text-[hsl(22_67%_38%)]', green: 'bg-[hsl(145_34%_44%/.14)] text-[hsl(145_34%_32%)]', red: 'bg-[hsl(var(--destructive)/.12)] text-[hsl(var(--destructive))]' };
  return <span data-testid="status-badge" className={`inline-flex items-center rounded-full px-2.5 py-1 text-[11px] font-bold uppercase tracking-[.08em] ${colors[tone]}`}>{children}</span>;
}
function Avatar({ name, large = false }: { name: string; large?: boolean }) {
  return <div data-testid={`avatar-${name.replace(/\s/g, '-').toLowerCase()}`} className={`flex shrink-0 items-center justify-center rounded-full bg-[hsl(var(--primary)/.14)] font-bold text-[hsl(var(--primary))] ${large ? 'h-16 w-16 text-lg' : 'h-10 w-10 text-xs'}`}>{initials(name)}</div>;
}
function Loading({ label = 'Loading your workspace' }: { label?: string }) {
  return <div className="space-y-4 p-1" data-testid="state-loading"><div className="skeleton h-28 rounded-2xl" /><div className="grid gap-4 md:grid-cols-3"><div className="skeleton h-32 rounded-2xl" /><div className="skeleton h-32 rounded-2xl" /><div className="skeleton h-32 rounded-2xl" /></div><p className="font-mono-ui text-xs text-muted-foreground">{label}</p></div>;
}
function QueryState({ error, empty, onRetry }: { error?: boolean; empty?: boolean; onRetry?: () => void }) {
  if (error) return <div className="rounded-2xl border border-[hsl(var(--destructive)/.3)] bg-[hsl(var(--destructive)/.06)] p-8 text-center" data-testid="state-error"><X className="mx-auto mb-3 text-destructive" /><h3 className="font-display text-lg font-bold">That view could not load</h3><p className="mt-1 text-sm text-muted-foreground">The network may have blinked. Try the request again.</p><Button variant="outline" onClick={onRetry} className="mt-4" testId="button-retry">Retry</Button></div>;
  if (empty) return <div className="rounded-2xl border border-dashed border-border bg-card p-12 text-center" data-testid="state-empty"><Compass className="mx-auto mb-3 h-8 w-8 text-[hsl(var(--primary))]" /><h3 className="font-display text-xl font-bold">Nothing here yet</h3><p className="mx-auto mt-2 max-w-sm text-sm text-muted-foreground">As the network moves, this space will fill with the work that matters to you.</p></div>;
  return null;
}

