  return <><PageHeader eyebrow="Marketplace / projects" title="Find work with a point of view." description="Browse live briefs from clients looking for architecture, design, engineering and construction partners." action={<Link href="/create-project" className="inline-flex items-center gap-2 rounded-lg bg-[hsl(var(--primary))] px-4 py-2.5 text-sm font-bold text-[hsl(var(--primary-foreground))]" data-testid="link-projects-create"><Plus size={16} />Post a project</Link>} /><div className="mb-7 grid gap-3 rounded-2xl border border-border bg-card p-3 md:grid-cols-[1fr_190px_auto]"><label className="flex items-center gap-3 rounded-lg bg-muted px-3"><Search size={17} className="text-muted-foreground" /><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search places, briefs or disciplines" className="w-full bg-transparent py-3 text-sm outline-none" data-testid="input-project-search" /></label><select value={type} onChange={(e) => setType(e.target.value)} className="rounded-lg border-0 bg-muted px-3 text-sm font-semibold outline-none" data-testid="select-project-type"><option value="">All project types</option><option>Residential</option><option>Commercial</option><option>Civic</option><option>Infrastructure</option></select><Button variant="soft" onClick={() => { setSearch(''); setType(''); }} testId="button-clear-filters"><Filter size={15} />Reset</Button></div>{query.isLoading ? <Loading label="Scanning briefs across the network" /> : query.isError && !query.data ? <QueryState error onRetry={() => query.refetch()} /> : data.length === 0 ? <QueryState empty /> : <div className="grid gap-4 lg:grid-cols-2">{data.map((project, index) => <ProjectCard project={project} key={project.id} featured={index === 0} />)}</div>}</>;
