function ProjectDetailPage() {
  const { id = 'p-104' } = useParams<{ id: string }>(); const query = useGetProject(id, { query: { queryKey: getGetProjectQueryKey(id) } }); const project = query.data; const [proposalOpen, setProposalOpen] = useState(false);
  if (query.isLoading) return <Loading label="Finding the shape of this brief" />; if (query.isError || !project) return <QueryState error onRetry={() => query.refetch()} />;
  return <><Link href="/projects" className="mb-6 inline-flex items-center gap-2 text-sm font-bold text-muted-foreground hover:text-foreground" data-testid="link-back-projects"><ArrowLeft size={16} />All projects</Link><div className="grid gap-7 xl:grid-cols-[1.4fr_.6fr]"><div><div className="flex flex-wrap items-center gap-2"><Badge tone="teal">{project.status}</Badge><span className="font-mono-ui text-xs text-muted-foreground">Brief {project.id}</span></div><h1 className="display-title mt-5 max-w-4xl text-5xl font-bold sm:text-7xl">{project.title}</h1><p className="mt-6 max-w-3xl text-lg leading-8 text-muted-foreground">{project.description}</p><div className="mt-8 flex flex-wrap gap-2">{project.requiredServices.map((service) => <Badge key={service} tone="neutral">{service}</Badge>)}</div><div className="mt-10 grid grid-cols-2 gap-5 border-y border-border py-6 sm:grid-cols-4"><div><p className="label">Location</p><p className="value"><MapPin size={14} />{project.city}, {project.country}</p></div><div><p className="label">Budget</p><p className="value">{money(project.budget, project.currency)}</p></div><div><p className="label">Scale</p><p className="value">{project.area.toLocaleString()} m²</p></div><div><p className="label">Timeline</p><p className="value"><Clock3 size={14} />{project.timeline}</p></div></div><section className="mt-10"><div className="flex items-center justify-between"><div><p className="label text-[hsl(var(--primary))]">Deterministic matching</p><h2 className="mt-1 font-display text-3xl font-bold">A shortlist with reasons.</h2></div><span className="font-mono-ui text-xs text-muted-foreground">{project.matches?.length || project.matchCount} matches</span></div><div className="mt-5 space-y-3">{(project.matches || []).map((match) => <div key={match.id} className="lift flex flex-col gap-4 rounded-xl border border-border bg-card p-4 sm:flex-row sm:items-center" data-testid={`match-${match.id}`}><Avatar name={match.professional.name} /><div className="min-w-0 flex-1"><p className="font-bold">{match.professional.name}</p><p className="text-sm text-muted-foreground">{match.professional.specialization} · {match.professional.city}</p><div className="mt-2 flex flex-wrap gap-1">{match.reasons.map((reason) => <span className="text-[11px] font-semibold text-[hsl(var(--primary))]" key={reason}>+ {reason}</span>)}</div></div><div className="text-right"><p className="font-display text-2xl font-bold text-[hsl(var(--primary))]">{match.score}%</p><Button variant="outline" testId={`button-invite-${match.id}`} onClick={() => setProposalOpen(true)}>Invite</Button></div></div>)}</div></section></div><aside className="h-fit rounded-2xl border border-border bg-card p-6 xl:sticky xl:top-24"><p className="label">Interested in this brief?</p><h2 className="mt-3 font-display text-2xl font-bold">Put your name forward.</h2><p className="mt-3 text-sm leading-6 text-muted-foreground">Tell {project.clientName || 'the client'} how you would approach the work.</p><Button className="mt-6 w-full" onClick={() => setProposalOpen(true)} testId="button-submit-proposal"><Send size={16} />Submit a proposal</Button><div className="mt-6 border-t border-border pt-5 text-xs leading-5 text-muted-foreground"><LockKeyhole size={14} className="mb-2 text-[hsl(var(--primary))]" />Your details are shared only with this project team.</div></aside></div>{proposalOpen && <ProposalDialog project={project} onClose={() => setProposalOpen(false)} />}</>;
}
function ProposalDialog({ project, onClose }: { project: Project; onClose: () => void }) {
  const create = useCreateProposal(); const qc = useQueryClient(); const [form, setForm] = useState({ fee: '', currency: project.currency, timeline: '', scope: '', deliverables: '', message: '' }); const [done, setDone] = useState(false);
  const submit = (e: FormEvent) => { e.preventDefault(); create.mutate({ id: project.id, data: { fee: Number(form.fee), currency: form.currency, timeline: form.timeline, scope: form.scope, deliverables: form.deliverables.split(',').map((x) => x.trim()).filter(Boolean), message: form.message } }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getGetProjectQueryKey(project.id) }); qc.invalidateQueries({ queryKey: getListProposalsQueryKey() }); setDone(true); } }); };
  return <div className="fixed inset-0 z-40 flex items-end justify-center bg-[#17363a]/60 p-3 backdrop-blur-sm sm:items-center"><div className="max-h-[92vh] w-full max-w-xl overflow-y-auto rounded-2xl border border-border bg-background p-6 shadow-2xl" role="dialog" data-testid="dialog-proposal"><div className="flex items-start justify-between"><div><p className="label text-[hsl(var(--primary))]">Proposal / {project.id}</p><h2 className="mt-1 font-display text-2xl font-bold">{done ? 'Proposal is on its way.' : 'Make a clear offer.'}</h2></div><button onClick={onClose} data-testid="button-close-proposal"><X /></button></div>{done ? <div className="py-12 text-center"><CheckCircle2 className="mx-auto h-12 w-12 text-[hsl(var(--primary))]" /><p className="mt-4 text-sm text-muted-foreground">The client can now review your scope, fee and timeline.</p><Button className="mt-6" onClick={onClose} testId="button-done-proposal">Back to brief</Button></div> : <form onSubmit={submit} className="mt-6 space-y-4"><div className="grid gap-4 sm:grid-cols-2"><label className="field"><span>Fee</span><input required type="number" value={form.fee} onChange={(e) => setForm({ ...form, fee: e.target.value })} placeholder="85000" data-testid="input-proposal-fee" /></label><label className="field"><span>Currency</span><select value={form.currency} onChange={(e) => setForm({ ...form, currency: e.target.value })} data-testid="select-proposal-currency"><option>EUR</option><option>USD</option><option>GBP</option><option>GHS</option></select></label></div><label className="field"><span>Timeline</span><input required value={form.timeline} onChange={(e) => setForm({ ...form, timeline: e.target.value })} placeholder="10 weeks to concept design" data-testid="input-proposal-timeline" /></label><label className="field"><span>Scope</span><textarea required value={form.scope} onChange={(e) => setForm({ ...form, scope: e.target.value })} placeholder="What exactly will you take responsibility for?" data-testid="textarea-proposal-scope" /></label><label className="field"><span>Deliverables <em>comma separated</em></span><input required value={form.deliverables} onChange={(e) => setForm({ ...form, deliverables: e.target.value })} placeholder="Concept package, planning set, ..." data-testid="input-proposal-deliverables" /></label><label className="field"><span>Message</span><textarea required value={form.message} onChange={(e) => setForm({ ...form, message: e.target.value })} placeholder="A short note to the project team" data-testid="textarea-proposal-message" /></label><Button type="submit" className="w-full" disabled={create.isPending} testId="button-send-proposal">{create.isPending ? <Loader2 className="animate-spin" size={16} /> : <Send size={16} />}Send proposal</Button>{create.isError && <p className="text-sm text-destructive" data-testid="text-proposal-error">We could not send that proposal. Try again.</p>}</form>}</div></div>;
}

