function Router() {
  const [location] = useLocation(); const publicRoute = location === '/' || location === '/login' || location.startsWith('/sign-in') || location.startsWith('/sign-up') || location.startsWith('/professionals/') || location.startsWith('/projects/');
  return <ErrorBoundary resetKey={location}>{publicRoute ? <Switch><Route path="/" component={Home} /><Route path="/login" component={LoginPage} /><Route path="/sign-in/*?" component={ClerkSignInPage} /><Route path="/sign-up/*?" component={ClerkSignUpPage} /><Route path="/projects/:id" component={ProjectDetailPage} /><Route path="/projects" component={ProjectsPage} /><Route path="/professionals/:id" component={ProfessionalDetailPage} /><Route path="/professionals" component={ProfessionalsPage} /><Route path="/companies" component={CompaniesPage} /><Route component={NotFound} /></Switch> : <Switch><Route path="/admin" component={AdminRoute} /><Route path="/dashboard" component={DashboardPage} /><Route path="/create-project" component={CreateProjectPage} /><Route path="/proposals" component={ProposalsPage} /><Route path="/contracts" component={ContractsPage} /><Route path="/workspace/:projectId" component={WorkspacePage} /><Route path="/profile" component={ProfilePage} /><Route path="/projects" component={ProjectsPage} /><Route path="/professionals" component={ProfessionalsPage} /><Route path="/companies" component={CompaniesPage} /><Route component={() => <AppShell><NotFound /></AppShell>} /></Switch>}</ErrorBoundary>;
}
function ClerkApp() {
  const [, setLocation] = useLocation();
  return <ClerkProvider publishableKey={clerkPubKey} proxyUrl={clerkProxyUrl} appearance={clerkAppearance} signInUrl={`${basePath}/sign-in`} signUpUrl={`${basePath}/sign-up`} routerPush={(to) => setLocation(stripBase(to))} routerReplace={(to) => setLocation(stripBase(to), { replace: true })}><QueryClientProvider client={queryClient}><TooltipProvider><Router /><Toaster /></TooltipProvider></QueryClientProvider></ClerkProvider>;
}
function App() {
  return <WouterRouter base={basePath}><ClerkApp /></WouterRouter>;
}
export default App;